import{_ as a,o as i,c as e,ao as t}from"./chunks/framework.CKOtou8s.js";const c=JSON.parse('{"title":"2D forward modelling","description":"","frontmatter":{},"headers":[],"relativePath":"forward/2d.md","filePath":"forward/2d.md","lastUpdated":null}'),n={name:"forward/2d.md"};function l(h,s,p,d,r,o){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="2D-forward-modelling" tabindex="-1">2D forward modelling <a class="header-anchor" href="#2D-forward-modelling" aria-label="Permalink to &quot;2D forward modelling {#2D-forward-modelling}&quot;">​</a></h1><p>In 2D the resistivity changes along a profile and with depth, but not along the geological strike. The MT fields then split into two independent modes: TE (electric field along strike) and TM (magnetic field along strike). MTGeophysics.jl solves both with finite differences on a rectangular mesh, including topography and lakes.</p><p>In this section we compute the 2D response of a model. A forward run needs three files: a model, a data file giving the stations and frequencies, and a forward control file. It writes <code>data.pred</code>.</p><h2 id="Run-the-example" tabindex="-1">Run the example <a class="header-anchor" href="#Run-the-example" aria-label="Permalink to &quot;Run the example {#Run-the-example}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helpers/benchmarks_2D.jl</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # writes examples/data/2D-IV</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/run_fwd2D.jl</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # model.true -&gt; data.pred</span></span></code></pre></div><p>To use your own files:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/run_fwd2D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.rho</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data.dat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FwdCtrl</span></span></code></pre></div><h2 id="The-forward-control-file" tabindex="-1">The forward control file <a class="header-anchor" href="#The-forward-control-file" aria-label="Permalink to &quot;The forward control file {#The-forward-control-file}&quot;">​</a></h2><p><code>fwd.ctrl</code> sets the mode, the strike and the air above the model. The example (<code>examples/ctrl/2D/FwdCtrl</code>) looks like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Mode                     : TETM</span></span>
<span class="line"><span>Strike (deg)             : auto</span></span>
<span class="line"><span>Air layers               : 10</span></span>
<span class="line"><span>Air thickness (m)        : 50000</span></span>
<span class="line"><span>Air growth factor        : 2</span></span>
<span class="line"><span>Air resistivity (ohm m)  : 1e+09</span></span>
<span class="line"><span>Write Frechet derivative : no</span></span>
<span class="line"><span>Dipole length (m)        : 100</span></span></code></pre></div><p>Most of the time you only change the first two lines. <code>Mode</code> is <code>TE</code>, <code>TM</code> or <code>TETM</code>. <code>Strike</code> is <code>auto</code> or an angle in degrees; the data are rotated to it before the run (see <a href="./../data/rotation">Rotation and strike</a>).</p><h2 id="From-Julia" tabindex="-1">From Julia <a class="header-anchor" href="#From-Julia" aria-label="Permalink to &quot;From Julia {#From-Julia}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MTGeophysics</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pred </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ForwardSolve2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;model.rho&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;FwdCtrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># writes data.pred next to data.dat</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PlotData2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; predicted_path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pred, output_path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;DataFit.png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The second line plots the observed and predicted apparent resistivity and phase, so you can compare them (see <a href="./../visualisation/2d">2D plots</a>).</p><h2 id="Working-in-memory" tabindex="-1">Working in memory <a class="header-anchor" href="#Working-in-memory" aria-label="Permalink to &quot;Working in memory {#Working-in-memory}&quot;">​</a></h2><p>If you want to change the model in a script, for example inside your own inversion, work with the mesh and resistivity directly:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mesh, ρ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Mesh2DFromInputs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ReadModel2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;model.rho&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">load_data2d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ReadFwdCtrl2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;FwdCtrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">response </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> run_mt2d_forward</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(mesh, ρ; mode </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :TETM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><code>response</code> holds the TE and TM impedances, apparent resistivities and phases, per frequency and station.</p><h2 id="Benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#Benchmarks" aria-label="Permalink to &quot;Benchmarks {#Benchmarks}&quot;">​</a></h2><p><code>helpers/benchmarks_2D.jl</code> writes four test cases into <code>examples/data/</code>. The stations run east–west near Jyväskylä, Finland, one every kilometre.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Case</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;">2D-I</td><td style="text-align:left;">a thin conductive dyke in a two-layer earth</td></tr><tr><td style="text-align:left;">2D-II</td><td style="text-align:left;">two resistive blocks in a two-layer earth</td></tr><tr><td style="text-align:left;">2D-III</td><td style="text-align:left;">conductors and resistors in a three-layer earth</td></tr><tr><td style="text-align:left;">2D-IV</td><td style="text-align:left;">2D-III under 100–200 m of hills and a 3 km lake, with <code>topo.dat</code> (the default)</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helpers/benchmarks_2D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2D-I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2D-II</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2D-III</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2D-IV</span></span></code></pre></div><p>The data of each case are computed on a finer mesh than the one the inversion uses, so an inversion cannot fit them by simply reproducing the forward mesh.</p>`,23)])])}const g=a(n,[["render",l]]);export{c as __pageData,g as default};
